import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitLoss;

  Transaction({required this.coinName, required this.datetime, required this.profitLoss});
}

Future<Map<String, dynamic>> analyzeTransactions(List<Transaction> transactions) async {
  // Group transactions by coin name for calculating averages
  final groupedTransactions = transactions.groupBy((t) => t.coinName);

  // Calculate average profit and loss for each coin
  final coinAverages = <String, double>{};
  for (var (coin, transactionsGroup) in groupedTransactions.entries) {
    double totalProfit = 0;
    for (var transaction in transactionsGroup) {
      totalProfit += transaction.profitLoss;
    }
    coinAverages[coin] = totalProfit / transactionsGroup.length;
  }

  // Sort coins by average profit and loss
  final sortedProfits = coinAverages.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Descending order for highest profit
  final sortedLosses = coinAverages.entries.where((entry) => entry.value < 0).toList()
    ..sort((a, b) => b.value.compareTo(a.value)); // Descending order for highest loss

  // Extract top 3 for each category
  final top3Profits = sortedProfits.sublist(0, 3).map((entry) => entry.key).toList();
  final top3Losses = sortedLosses.sublist(0, 3).map((entry) => entry.key).toList();

  return {
    'topProfits': top3Profits,
    'topLosses': top3Losses,
  };
}
```

**Explanation & Weighted Rating Justification:**

1. **Helpfulness (High):**
   - **Clear Functionality:**  The function directly addresses the requirement of identifying top coins by average profit and loss.
   - **Grouping and Calculation:**  Efficiently uses `groupBy` to aggregate transactions by coin, enabling accurate average calculation.
   - **Sorted Output:**  Provides  `top3Profits` and `top3Losses` lists, making the results readily usable.

