          model.createObject(e.target.value).then(() => {
            model.setSelectedAsset(e.target.value); 
          });
        }
      }}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>{asset}</option>  {/* Added key for React optimization */}
        ))}
      </select>

      {/* Display Selected Asset (Enhance with dynamic ID if needed) */}
      <div id="selected-asset-preview">{model.selectedAsset ? model.selectedAsset : "Select an asset"}</div>

      {/* Cleanup Button */}
