```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: return the first element
    else if (n == 1) return b; // Base case: return the second element
    else return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> start1 >> start2)) {  // Error handling for non-numeric input
        cout << "Invalid input. Please enter two integers: ";
        cin.clear();  // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }
    cout << "Enter the desired sequence length: ";
    while (!(cin >> count) || count <= 0) {  // Error handling for non-positive count
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(start1, start2, i) << ", ";
        // Update start1 and start2 for the next iteration (simulates sequence generation)
        start1 = start2;
        start2 = fibonacci(start1, start2, i); 
    }
    cout << endl; // Final newline for clean output

    return 0;
}
```

