// **Vertical Video Merger & Subtitle Script (After Effects)**

// --- CONFIGURATION ---
const desktopPath = File(eval('System.desktop')).path; // Get Desktop path
const footageFolder = desktopPath + "/your_video_folder"; // Adjust folder name accordingly
const file1 = "file1.mp4";  // Replace with your top video filename
const file2 = "file2.mp4";  // Replace with your bottom video filename
const subtitleFile = "subtitles.txt"; // Replace with your subtitle text file
const fontSize = 30;          // Subtitle font size (adjust as needed)
const fontFace = "Arial";      // Choose your desired font

// --- SCRIPT LOGIC ---

app.project.activeItem = new CompItem(width: 1080, height: 1920, name: "VerticalVideo"); // Create new comp (portrait)

// 1. Import Footage Layers
var layer1 = app.project.importFile(footageFolder + "/" + file1);
layer1.transform.position = [0, 0]; // Top-left corner
layer1.scale = [1, 1]; // Maintain aspect ratio
layer1.height = app.project.activeItem.height / 2; // Occupy top half

var layer2 = app.project.importFile(footageFolder + "/" + file2);
layer2.transform.position = [0, layer1.height]; // Stacked below layer1
layer2.scale = [1, 1];
layer2.height = app.project.activeItem.height / 2; // Occupy bottom half

// 2. Load and Display Subtitles (Layer on top of layer1)
var subtitleText = File(footageFolder + "/" + subtitleFile).readText().split("\n"); // Read subtitles line by line
var subtitleLayer = new TextLayer();
subtitleLayer.text = subtitleText.join("\n"); 
subtitleLayer.fontSize = fontSize;
subtitleLayer.fontFamily = fontFace;
subtitleLayer.textColor = rgb(255, 255, 255); // White color (adjust as needed)
subtitleLayer.transform.position = [0, layer1.height - subtitleLayer.contentHeight - 10]; // Bottom of layer1 with spacing

